#!/usr/bin/perl
use strict; use warnings;
use MIME::Base64 qw(encode_base64);
use POSIX ();

my $BIN = "/workspace/dataset/test7_executable";
die "no binary" unless -x $BIN;

############ spec v1 predictor ############
sub f32 { return unpack('f', pack('f', $_[0])); }

sub wrap32 {
    my $x = $_[0];
    my $m = $x % 4294967296;
    $m -= 4294967296 if $m >= 2147483648;
    return $m;
}

# std::stoi (C locale, base 10) -> ('ok',v) | ('invalid_argument',undef) | ('out_of_range',undef)
sub stoi {
    my ($s) = @_;
    my $n = length($s);
    my $i = 0;
    $i++ while $i < $n && substr($s,$i,1) =~ /\A[ \t\n\x0b\f\r]\z/;
    my $sign = 1;
    if ($i < $n) {
        my $c = substr($s,$i,1);
        if    ($c eq '+') { $i++; }
        elsif ($c eq '-') { $sign = -1; $i++; }
    }
    my $d = '';
    while ($i < $n && substr($s,$i,1) =~ /\A[0-9]\z/) { $d .= substr($s,$i,1); $i++; }
    return ('invalid_argument', undef) if $d eq '';
    $d =~ s/\A0+//; $d = '0' if $d eq '';
    my $lim = $sign > 0 ? '2147483647' : '2147483648';
    my $over = 0;
    if    (length($d) > length($lim)) { $over = 1; }
    elsif (length($d) == length($lim) && $d gt $lim) { $over = 1; }
    return ('out_of_range', undef) if $over;
    return ('ok', $sign * ($d + 0));
}

# P = (f32)current * 100.0f / (f32)total   (all in f32)
sub pct_f32 {
    my ($cur, $tot) = @_;
    return f32( f32( f32($cur) * f32(100.0) ) / f32($tot) );
}

sub disp_line {
    my ($cur, $tot) = @_;
    return sprintf("Progress: %.1f%% (%d/%d)", pct_f32($cur,$tot), $cur, $tot);
}

sub predict {
    my ($args) = @_;                 # arrayref of argv[1..]
    my $TOTAL = 200;
    my ($cur, $kind);
    if (scalar(@$args) >= 1) {
        my ($st, $v) = stoi($args->[0]);
        if ($st ne 'ok') {
            my $ex = $st eq 'invalid_argument' ? 'std::invalid_argument' : 'std::out_of_range';
            my $se = "terminate called after throwing an instance of '$ex'\n  what():  stoi\n";
            return { stdout => '', stderr => $se, code => 0, sig => 6 };
        }
        $cur = $v;
    } else {
        $cur = 150;
    }
    my $l1 = disp_line($cur, $TOTAL);
    my $cur2 = wrap32($cur + 25);
    my $l2 = disp_line($cur2, $TOTAL);
    my $p1 = sprintf("%.1f%%", f32(f32(0.15) * f32(100.0)));
    my $p2 = sprintf("%.2f%%", f32(f32(0.35) * f32(100.0)));
    my $p3 = sprintf("%.3f%%", f32(f32(0.65) * f32(100.0)));
    return { stdout => "$l1\n$l2\n$p1\n$p2\n$p3\n", stderr => '', code => 0, sig => 0 };
}

############ runner ############
sub slurp { my ($p)=@_; open(my $fh,'<',$p) or return ''; binmode $fh; local $/; my $d=<$fh>; close $fh; return defined $d ? $d : ''; }

my $SEQ = 0;
sub run_case {
    my ($args) = @_;
    $SEQ++;
    my $o = "/tmp/_h_o.$$.$SEQ"; my $e = "/tmp/_h_e.$$.$SEQ";
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDIN,  '<', '/dev/null');
        open(STDOUT, '>', $o) or POSIX::_exit(127);
        open(STDERR, '>', $e) or POSIX::_exit(127);
        exec {$BIN} ($BIN, @$args);
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?;
    my $code = $st >> 8;
    my $sig  = $st & 127;
    my $so = slurp($o); my $se = slurp($e);
    unlink $o, $e;
    return { stdout=>$so, stderr=>$se, code=>$code, sig=>$sig };
}

sub b64 { my $s = encode_base64($_[0], ''); return $s eq '' ? '-' : $s; }
sub esc {
    my ($s) = @_;
    my $r = '';
    for my $c (split //, $s) {
        my $o = ord($c);
        if    ($c eq "\n") { $r .= '\n' }
        elsif ($c eq "\t") { $r .= '\t' }
        elsif ($c eq "\r") { $r .= '\r' }
        elsif ($c eq "\\") { $r .= '\\\\' }
        elsif ($o < 0x20 || $o > 0x7e) { $r .= sprintf('\x%02x', $o) }
        else { $r .= $c }
    }
    return $r;
}

############ case list ############
my @cases;   # [label, [args]]
sub add { my ($label, @a) = @_; push @cases, [$label, [@a]]; }

add("no-args");
add("int:$_", "$_") for (-30..30);                    # covers -20..20 and 0/1 nbhd
add("int:$_", "$_") for (169..231);                   # 199/200/201 +-30
add("int:$_", "$_") for (2147483617..2147483647);     # INT_MAX-30..INT_MAX
add("int:$_", "$_") for (-2147483648..-2147483618);   # INT_MIN..INT_MIN+30
# increment-overflow boundary + INT_MAX-25 explicitly (already in range, kept for clarity)
add("bnd:$_", "$_") for (2147483622, 2147483623, 2147483624);

# f32 integer-precision loss neighbourhoods
my @prec;
push @prec, ($_) for (8388605..8388611);
push @prec, ($_) for (16777210..16777230);
push @prec, ($_) for (33554425..33554445);
push @prec, ($_) for (67108860..67108875);
push @prec, (100000001, 100000003, 100000005, 1000000001, 1000000003, 999999999,
             123456789, 1073741823, 1073741824, 1073741825, 2000000000, 2000000001,
             1234567891, 1999999999, 536870913, 268435457, 134217729);
push @prec, map { -$_ } (16777215,16777216,16777217,16777219,16777221,33554433,
             100000001,1000000001,1073741825,2000000001,123456789);
add("prec:$_", "$_") for @prec;

# malformed / tricky strings
my @tricky = (
  ['empty',            ''],
  ['single-space',     ' '],
  ['abc',              'abc'],
  ['0x1f',             '0x1f'],
  ['0X1F',             '0X1F'],
  ['12abc',            '12abc'],
  ['spc-neg0-spc',     '  -0  '],
  ['neg0',             '-0'],
  ['pos0',             '+0'],
  ['007',              '007'],
  ['010',              '010'],
  ['tab42',            "\t42"],
  ['nl42',             "\n42"],
  ['vtab42',           "\x0b42"],
  ['ff42',             "\f42"],
  ['cr42',             "\r42"],
  ['allws42',          " \t\n\x0b\f\r42"],
  ['ws-then-sign',     "  +7"],
  ['ws-sign-ws-dig',   "  +  7"],
  ['42-trailing-ws',   "42  "],
  ['ws-both',          "  33  "],
  ['int-max-plus1',    '2147483648'],
  ['int-min-minus1',   '-2147483649'],
  ['int-max',          '2147483647'],
  ['int-min',          '-2147483648'],
  ['twenty-nines',     '99999999999999999999'],
  ['long-long-max',    '9223372036854775807'],
  ['long-long-ovf',    '9223372036854775808'],
  ['digits5000',       '9' x 5000],
  ['zeros5000then7',   ('0' x 5000) . '7'],
  ['zeros5000',        '0' x 5000],
  ['neg-zeros5000then7', '-' . ('0' x 5000) . '7'],
  ['arabic-indic-3',   "\x{d9}\x{a3}"],
  ['fullwidth-3',      "\x{ef}\x{bc}\x{93}"],
  ['comma1000',        '1,000'],
  ['space-sep',        '1 2'],
  ['double-dash-1',    '--1'],
  ['plus-minus-3',     '+-3'],
  ['dash-space-5',     '- 5'],
  ['dot5',             '.5'],
  ['3dot9',            '3.9'],
  ['2e3',              '2e3'],
  ['1_000',            '1_000'],
  ['underscore-lead',  '_1'],
  ['plus7',            '+7'],
  ['inf',              'inf'],
  ['nan',              'nan'],
  ['minus-inf',        '-inf'],
  ['nbsp42',           "\x{c2}\x{a0}42"],
  ['nul-ish-esc',      '\\0'],
  ['150-exact',        '150'],
  ['neg1',             '-1'],
  ['1e0',              '1e0'],
  ['0b101',            '0b101'],
  ['tab-only',         "\t"],
  ['newline-only',     "\n"],
  ['sign-only-plus',   '+'],
  ['sign-only-minus',  '-'],
  ['high-byte-ff',     "\xff"],
  ['42-then-nl',       "42\n"],
  ['leading-zeros-max','0000002147483647'],
  ['leading-zeros-ovf','0000002147483648'],
);
add("str:$_->[0]", $_->[1]) for @tricky;

# multiple args
add("args2", '10', '99');
add("args3", '10', 'abc', '-5');
add("args2-bad-first", 'abc', '10');
add("args2-empty-first", '', '10');
add("args5", '7', 'a', 'b', 'c', 'd');

############ execute ############
my @records;
my @mismatch;
for my $c (@cases) {
    my ($label, $args) = @$c;
    my $got = run_case($args);
    my $exp = predict($args);
    my $ok = ($got->{stdout} eq $exp->{stdout})
          && ($got->{stderr} eq $exp->{stderr})
          && ($got->{code}   == $exp->{code})
          && ($got->{sig}    == $exp->{sig});
    push @mismatch, [$label, $args, $got, $exp] unless $ok;
    push @records, [$label, $args, $got, $ok];
}

open(my $G, '>', '/tmp/golden_blackbox.txt') or die $!;
binmode $G;
print $G "# GOLDEN TABLE for /workspace/dataset/test7_executable\n";
print $G "# Generated by /tmp/harness.pl (pure black-box: fork+exec, stdout/stderr captured to SEPARATE files)\n";
print $G "# Fields per record:\n";
print $G "#   CASE   <ordinal> <label>\n";
print $G "#   ARGC   <number of argv entries AFTER argv[0]>\n";
print $G "#   ARG    <index> <base64 of the raw argv bytes>   (one line per arg; '-' means empty string)\n";
print $G "#   EXIT   <waitpid exit code>\n";
print $G "#   SIGNAL <terminating signal number, 0 if none>\n";
print $G "#   SHELLSTATUS <what \$? shows in a shell: 128+signal when signalled>\n";
print $G "#   OUT_B64 / ERR_B64  <base64 of the exact bytes; '-' means empty>\n";
print $G "#   OUT_ESC / ERR_ESC  <same bytes, C-escaped, for human reading>\n";
print $G "#   SPECV1 <MATCH|MISMATCH> against the derived spec v1 predictor\n";
print $G "#\n";
my $i = 0;
for my $r (@records) {
    my ($label, $args, $got, $ok) = @$r;
    $i++;
    print $G "CASE   $i $label\n";
    print $G "ARGC   " . scalar(@$args) . "\n";
    for my $k (0..$#$args) { print $G "ARG    $k " . b64($args->[$k]) . "\n"; }
    my $shell = $got->{sig} ? 128 + $got->{sig} : $got->{code};
    print $G "EXIT   $got->{code}\n";
    print $G "SIGNAL $got->{sig}\n";
    print $G "SHELLSTATUS $shell\n";
    print $G "OUT_B64 " . b64($got->{stdout}) . "\n";
    print $G "ERR_B64 " . b64($got->{stderr}) . "\n";
    print $G "OUT_ESC " . esc($got->{stdout}) . "\n";
    print $G "ERR_ESC " . esc($got->{stderr}) . "\n";
    print $G "SPECV1 " . ($ok ? "MATCH" : "MISMATCH") . "\n";
    print $G "ENDCASE\n";
}
close $G;

print "TOTAL CASES: " . scalar(@records) . "\n";
print "MISMATCHES vs spec v1: " . scalar(@mismatch) . "\n";
for my $m (@mismatch) {
    my ($label, $args, $got, $exp) = @$m;
    print "----- MISMATCH: $label\n";
    print "  args: " . join(' | ', map { esc($_) } @$args) . "\n";
    print "  got  out: " . esc($got->{stdout}) . "\n";
    print "  exp  out: " . esc($exp->{stdout}) . "\n";
    print "  got  err: " . esc($got->{stderr}) . "\n";
    print "  exp  err: " . esc($exp->{stderr}) . "\n";
    print "  got  code=$got->{code} sig=$got->{sig} | exp code=$exp->{code} sig=$exp->{sig}\n";
}

