use strict; use warnings;
no warnings 'exec';
use POSIX ();

my $BIN = "/workspace/dataset/test7_executable";
die "no binary" unless -x $BIN;
$| = 1;

my @B64TBL = ('A'..'Z','a'..'z','0'..'9','+','/');
sub encode_base64 {
    my ($d) = @_;
    return '' if !defined $d || $d eq '';
    my $bits = unpack('B*', $d);
    my $pad = (6 - (length($bits) % 6)) % 6;
    $bits .= '0' x $pad;
    my $out = '';
    while ($bits =~ /\G(.{6})/gs) { $out .= $B64TBL[oct("0b$1")]; }
    $out .= '=' x ($pad == 4 ? 2 : ($pad == 2 ? 1 : 0));
    return $out;
}
sub b64 { my $s = encode_base64($_[0]); return $s eq '' ? '-' : $s; }
sub esc {
    my ($s) = @_; my $r = '';
    for my $c (split //, $s) {
        my $o = ord($c);
        if    ($c eq "\n") { $r .= '\n' } elsif ($c eq "\t") { $r .= '\t' }
        elsif ($c eq "\r") { $r .= '\r' } elsif ($c eq "\\") { $r .= '\\\\' }
        elsif ($o < 0x20 || $o > 0x7e) { $r .= sprintf('\x%02x', $o) }
        else { $r .= $c }
    }
    return $r;
}

sub f32 { return unpack('f', pack('f', $_[0])); }
sub wrap32 { my $m = $_[0] % 4294967296; $m -= 4294967296 if $m >= 2147483648; return $m; }

sub stoi {
    my ($s) = @_; my $n = length($s); my $i = 0;
    $i++ while $i < $n && substr($s,$i,1) =~ /\A[ \t\n\x0b\f\r]\z/;
    my $sign = 1;
    if ($i < $n) { my $c = substr($s,$i,1);
        if ($c eq '+') { $i++ } elsif ($c eq '-') { $sign = -1; $i++ } }
    my $d = '';
    while ($i < $n && substr($s,$i,1) =~ /\A[0-9]\z/) { $d .= substr($s,$i,1); $i++ }
    return ('invalid_argument', undef) if $d eq '';
    $d =~ s/\A0+//; $d = '0' if $d eq '';
    my $lim = $sign > 0 ? '2147483647' : '2147483648';
    return ('out_of_range', undef)
        if length($d) > length($lim) || (length($d) == length($lim) && $d gt $lim);
    return ('ok', $sign * ($d + 0));
}

# candidate percentage formulas
sub pct_A { my ($c,$t)=@_; return f32( f32( f32($c) * f32(100.0) ) / f32($t) ); } # mul-first f32
sub pct_B { my ($c,$t)=@_; return f32( f32( f32($c) / f32($t) ) * f32(100.0) ); } # div-first f32
sub pct_C { my ($c,$t)=@_; return ($c * 100.0) / $t; }                            # double mul-first
sub pct_D { my ($c,$t)=@_; return f32( f32(f32($c) / f32($t)) * 100.0 ); }        # f32 div, double mul
sub pct_E { my ($c,$t)=@_; return f32( f32($c) / f32($t) ) * 100.0; }             # f32 div, double mul, no final round

my %PCT = (A=>\&pct_A, B=>\&pct_B, C=>\&pct_C, D=>\&pct_D, E=>\&pct_E);

sub predict {
    my ($args, $fid) = @_;
    my $fn = $PCT{$fid};
    my $TOTAL = 200;
    my $cur;
    if (scalar(@$args) >= 1) {
        my ($st, $v) = stoi($args->[0]);
