    my $l2 = sprintf("Progress: %.1f%% (%d/%d)", $fn->($c2,$TOTAL), $c2, $TOTAL);
    my $p1 = sprintf("%.1f%%", f32(f32(0.15) * f32(100.0)));
    my $p2 = sprintf("%.2f%%", f32(f32(0.35) * f32(100.0)));
    my $p3 = sprintf("%.3f%%", f32(f32(0.65) * f32(100.0)));
    return { stdout=>"$l1\n$l2\n$p1\n$p2\n$p3\n", stderr=>'', code=>0, sig=>0 };
}

sub slurp { my ($p)=@_; open(my $fh,'<',$p) or return ''; binmode $fh; local $/; my $d=<$fh>; close $fh; return defined $d ? $d : ''; }
my $SEQ = 0;
sub run_case {
    my ($args) = @_; $SEQ++;
    my $o = "/tmp/_h2o.$$.$SEQ"; my $e = "/tmp/_h2e.$$.$SEQ";
