    if ($pid == 0) {
        open(STDIN,'<','/dev/null'); open(STDOUT,'>',$o) or POSIX::_exit(127);
        open(STDERR,'>',$e) or POSIX::_exit(127);
        exec {$BIN} ($BIN, @$args); POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $st = $?; my $so = slurp($o); my $se = slurp($e); unlink $o, $e;
    return { stdout=>$so, stderr=>$se, code=>$st >> 8, sig=>$st & 127 };
}

############ case list ############
my @cases; my %seen;
sub add { my ($label,@a)=@_; my $k = join("\x01", scalar(@a), @a); return if $seen{$k}++; push @cases,[$label,[@a]]; }
sub addint { my ($p,$v)=@_; add("$p:$v","$v"); }

