for my $e (22..30) { my $p = 2**$e; addint("pow2_$e", $p+$_) for (-12..12); }
addint("pow2n_$_", -(2**$_)) for (22..30);
for my $e (23..30) { my $p = 2**$e; addint("pow2neg_$e", -($p+$_)) for (-6..6); }

# dense f32-precision sweeps
addint("prec",$_) for (8388590..8388630);
addint("prec",$_) for (16777200..16777240);
addint("prec",$_) for (33554420..33554450);
addint("prec",$_) for (67108850..67108880);
