#!/usr/bin/perl
use strict; use warnings; no warnings 'exec';
use POSIX ();
my $BIN = "/workspace/dataset/test7_executable"; $|=1;
sub f32 { return unpack('f', pack('f', $_[0])); }
sub wrap32 { my $m = $_[0] % 4294967296; $m -= 4294967296 if $m >= 2147483648; return $m; }
sub B { my ($c,$t)=@_; return f32( f32( f32($c) / f32($t) ) * f32(100.0) ); }
sub predict {
    my ($cur) = @_; my $T=200; my $c2 = wrap32($cur+25);
    return sprintf("Progress: %.1f%% (%d/%d)\nProgress: %.1f%% (%d/%d)\n15.0%%\n35.00%%\n65.000%%\n",
        B($cur,$T), $cur, $T, B($c2,$T), $c2, $T);
}
sub slurp { my ($p)=@_; open(my $fh,'<',$p) or return ''; binmode $fh; local $/; my $d=<$fh>; close $fh; return defined $d?$d:''; }
my $S=0;
sub run1 {
    my ($v)=@_; $S++;
    my $o="/tmp/_s.o.$$"; my $e="/tmp/_s.e.$$";
    my $pid=fork(); die unless defined $pid;
    if(!$pid){ open(STDIN,'<','/dev/null'); open(STDOUT,'>',$o) or POSIX::_exit(127);
        open(STDERR,'>',$e) or POSIX::_exit(127); exec {$BIN} ($BIN,"$v"); POSIX::_exit(127); }
    waitpid($pid,0); my $st=$?; my $so=slurp($o); my $se=slurp($e); unlink $o,$e;
    return ($so,$se,$st>>8,$st&127);
}
my @vals;
push @vals, (1638390..1638460);          # first real-deviation region
push @vals, (1342160..1342240);          # first A/B divergence region
push @vals, map { $_*997 } (1..400);     # spread small/mid
push @vals, map { -$_*997 } (1..200);
my $s=987654321;
for (1..1500) { $s = ($s*1103515245+12345) % 2147483648; push @vals, ($_%2 ? $s : -$s); }
for (1..600)  { $s = ($s*1103515245+12345) % 2147483648; push @vals, ($s % 20000000) * ($_%3?1:-1); }
push @vals, (2147483640..2147483647), (-2147483648..-2147483641);
my %u; @vals = grep { !$u{$_}++ && $_>=-2147483648 && $_<=2147483647 } @vals;
my $bad=0; my $n=0;
for my $v (@vals) {
    my ($so,$se,$c,$sig) = run1($v); $n++;
    my $exp = predict($v);
    if ($so ne $exp || $se ne '' || $c != 0 || $sig != 0) {
        $bad++; print "MISMATCH v=$v\n  got=$so  exp=$exp  err=$se code=$c sig=$sig\n" if $bad<=10;
    }
}
print "SWEEP: ran $n distinct currents through the binary; mismatches vs divide-first f32 = $bad\n";

